#!/usr/bin/env bash
# Bundle item 213_env_water5_pre (thread "Videos: Environment committee meetings", 24 Nov 2569). Asked by "Site: Update automatically
# three times a day" (24 Nov 05:52 UTC). ONE self-contained file: the video is embedded below as base64 tar.gz (sha256-checked).
# New: water subcommittee meeting 5 (Thu 26 Nov 2569) BEFORE-meeting video -> environment/2569/sub-water.html meeting 5
# (1080x1920, Thai voice + English subtitles burned in, one version). Source: notice ref 11236547 (ว1056), Rpublic=1.
# APPLY AFTER item 212 (it adds the water 5 date card).
# Surgical: adds only this video to the "media" field of that meeting, fills its CAPS caption track, makes the share page
# (video_share.py CARD_BIG=1), re-applies no_video_dl, refreshes the home newest-4 video list + Environment snapshot "v",
# then moves the mp4 to the video repos (video_offload.py). Idempotent; no git, no network. Needs $HUB ($BUILD optional).
set -euo pipefail
: "${HUB:?HUB not set}"; BUILD=${BUILD:-/mnt/project-files/archive/build}
L="$HUB/environment/2569"
test -f "$L/index.html" -a -f "$L/sub-water.html" -a -f "$L/meetings.json" -a -f "$L/sub-water.json" -a -f "$HUB/index.html" \
  || { echo "213_env_water5_pre: Environment pages missing" >&2; exit 1; }
python3 - "$L" <<'PY0' || { echo "213_env_water5_pre: apply item 212 first (water meeting 5 date card missing)" >&2; exit 1; }
import json, sys
L = sys.argv[1]
w = {f"{m['n']}|{m['date']}": m for m in json.load(open(f'{L}/sub-water.json', encoding='utf-8'))}
assert '5|2026-11-26' in w
PY0
W=$(mktemp -d); trap 'rm -rf "$W"' EXIT
sed -n '/^__PAYLOAD_BELOW__$/,$p' "$0" | tail -n +2 | base64 -d > "$W/p.tgz"
echo "236fbecbc5043fb74aed75145bb1f71bcc0cd16282bb90117f00a9499b3c6f52  $W/p.tgz" | sha256sum -c --quiet - || { echo "213_env_water5_pre: payload checksum mismatch" >&2; exit 1; }
mkdir "$W/m"; tar -xzf "$W/p.tgz" -C "$W/m"
SRC="$W/m"
for v in sub-water-v5pre:110; do f=${v%%:*}; want=${v##*:}
  test -s "$SRC/$f.mp4" -a -s "$SRC/$f.th.vtt" || { echo "213_env_water5_pre: $f missing in payload" >&2; exit 1; }
  dur=$(ffprobe -v error -show_entries format=duration -of csv=p=0 "$SRC/$f.mp4")
  python3 -c "import sys; sys.exit(0 if abs(float('$dur')-$want)<1.5 else 1)" || { echo "213_env_water5_pre: $f length $dur, expected ~$want s" >&2; exit 1; }
  wh=$(ffprobe -v error -select_streams v:0 -show_entries stream=width,height -of csv=p=0 "$SRC/$f.mp4"); [ "$wh" = "1080,1920" ] || { echo "213_env_water5_pre: $f size $wh" >&2; exit 1; }
  head -1 "$SRC/$f.th.vtt" | grep -q '^WEBVTT' || { echo "213_env_water5_pre: $f vtt header" >&2; exit 1; }
done
mkdir -p "$L/media" "$L/img"
for f in "$SRC"/*.mp4 "$SRC"/*.vtt; do b=$(basename "$f"); cmp -s "$f" "$L/media/$b" || cp -f "$f" "$L/media/$b"; done
for f in "$SRC"/*.jpg; do b=$(basename "$f"); cmp -s "$f" "$L/img/$b" || cp -f "$f" "$L/img/$b"; done
python3 - "$HUB" <<'PY'
import json, os, sys
HUB = sys.argv[1]; L = os.path.join(HUB, 'environment', '2569')
ADD = json.loads(r"""{
"sub-water.html": {
"5|2026-11-26": [
{
"src": "media/sub-water-v5pre.mp4",
"poster": "img/poster-sub-water-5pre.jpg",
"vtt": "media/sub-water-v5pre.th.vtt",
"kind": "pre",
"label": "วิดีโอก่อนการประชุม",
"dur": "1:50",
"cc": "เสียงบรรยายภาษาไทย มีคำบรรยายภาษาอังกฤษในวิดีโอ",
"ck": "water-5p"
}
]
}
}""")
JSONS = {'index.html': 'meetings.json', 'sub-water.html': 'sub-water.json'}
CMP = dict(ensure_ascii=False, separators=(',', ':'))
ser = lambda a: json.dumps(a, **CMP).replace('</', '<\\/')
changed = []

def put(path, text):
    if open(path, encoding='utf-8').read() != text:
        open(path, 'w', encoding='utf-8').write(text); changed.append(os.path.relpath(path, HUB))

def merged(old, new):
    old = json.loads(json.dumps(old or {}))
    vids = old.get('videos') or ([old['video']] if old.get('video') else [])
    cks = {v['ck'] for v in new}
    vids = [v for v in vids if v.get('ck') not in cks]
    for v in new:
        v = dict(v)
        loc = os.path.join(L, v['src'])
        if os.path.exists(loc): v['size'] = os.path.getsize(loc)
        vids.append(v)
    vids.sort(key=lambda v: 0 if v.get('kind') == 'pre' else 1)   # before-meeting video first (VIDEO ORDER)
    old['video'] = vids[0]; old['videos'] = vids
    return old

def jline(lines, prefix, dump):
    idx = [i for i, l in enumerate(lines) if l.startswith(prefix)]
    assert len(idx) == 1, f'{prefix} line not found once'
    line = lines[idx[0]]; body = line[len(prefix):]; tail = body[len(body.rstrip().rstrip(';')):]
    val = json.loads(body[:len(body) - len(tail)])
    assert prefix + dump(val) + tail == line, f'{prefix} line does not round-trip; not touching it'
    return idx[0], val, tail

for page, want in ADD.items():
    p = os.path.join(L, page); lines = open(p, encoding='utf-8').read().split('\n')
    i, arr, tail = jline(lines, 'const DATA=', ser)
    keys = {f"{m['n']}|{m['date']}": m for m in arr}
    for k, new in want.items():
        assert k in keys, f'{page}: meeting {k} not on the page'
        keys[k]['media'] = merged(keys[k].get('media'), new)
    lines[i] = 'const DATA=' + ser(arr) + tail
    i, caps, tail = jline(lines, 'const CAPS=', lambda a: json.dumps(a, ensure_ascii=False))
    for new in want.values():
        for v in new:
            caps[v['ck']] = open(os.path.join(L, v['vtt']), encoding='utf-8').read()
    lines[i] = 'const CAPS=' + json.dumps(caps, ensure_ascii=False) + tail
    put(p, '\n'.join(lines))
    p = os.path.join(L, JSONS[page]); raw = open(p, encoding='utf-8').read(); ms = json.loads(raw)
    assert json.dumps(ms, ensure_ascii=False, indent=1) == raw, f'{JSONS[page]} does not round-trip; not touching it'
    mk = {f"{m['n']}|{m['date']}": m for m in ms}
    for k, new in want.items():
        assert k in mk, f'{JSONS[page]}: meeting {k} missing'
        mk[k]['media'] = merged(mk[k].get('media'), new)
    put(p, json.dumps(ms, ensure_ascii=False, indent=1))

# home page: newest-4 video list (same rules as archive/hub/home.py) + Environment 2569 snapshot "v" counts
ms = json.load(open(os.path.join(L, 'meetings.json'), encoding='utf-8'))
p = os.path.join(HUB, 'index.html'); t = open(p, encoding='utf-8').read(); dec = json.JSONDecoder()
mark = 'const HH = '
if t.count(mark) == 1:
    i = t.index(mark) + len(mark); hh, _ = dec.raw_decode(t[i:])
    old_s = ser(hh['videos'])
    assert t.count(old_s) == 1, 'home: video list text not found once'
    env = []
    for m in ms:
        for v in (m.get('media') or {}).get('videos') or []:
            env.append(dict(n=m['n'], date=m['date'], year=2569, who='กมธ.ทรัพยากรธรรมชาติและสิ่งแวดล้อม', label=v.get('label') or 'วิดีโอสรุป',
                            dur=v.get('dur', ''), poster='environment/2569/' + v['poster'] if v.get('poster') else '',
                            headline='' if m.get('pending') else (m.get('headline') or ''), href=f"environment/2569/#read-{m['n']}"))
    seen = {(v['href'], v['poster']) for v in hh['videos']}
    vids = hh['videos'] + [v for v in env if (v['href'], v['poster']) not in seen]
    vids.sort(key=lambda v: v['date'], reverse=True)
    t = t.replace(old_s, ser(vids[:4]), 1)
else:
    print('213_env_water5_pre: home page has no HH list (skipped)')
dm = 'const DATA = '
assert t.count(dm) == 1, 'home: DATA not found once'
j = t.index(dm) + len(dm); hub, _ = dec.raw_decode(t[j:])
nv = {(m['n'], m['date']): len((m.get('media') or {}).get('videos') or []) for m in ms}
assert any(c.get('id') == 'environment' for c in hub), 'home: Environment committee not in DATA'
for c in hub:
    if c.get('id') != 'environment':
        continue
    for y in c.get('years', []):
        if y.get('year') != 2569:
            continue
        for s in y.get('snap') or []:
            want = nv.get((s['n'], s['date']))
            if want is not None and s.get('v') != want:
                a = ser(s); s['v'] = want; b = ser(s)
                assert t.count(a) == 1, f'home: snapshot entry {s["n"]} not found once'
                t = t.replace(a, b, 1)
put(p, t)
print('213_env_water5_pre: changed', len(changed), 'text files:', ', '.join(changed) or 'none (already applied)')
PY
CARD_BIG=1 python3 "$BUILD/video_share.py" "$L" https://parliamentx.com/environment/2569 2569
python3 "$BUILD/no_video_dl.py" "$L/s"
python3 "$BUILD/no_video_dl.py" --check "$L"
for f in v-water-5-pre; do test -f "$L/s/$f.html" || { echo "213_env_water5_pre: share page s/$f.html missing" >&2; exit 1; }; done
python3 - "$L" <<'PY'
import json, sys
L = sys.argv[1]
for page, ks in (('sub-water.html', ('5',)),):
    t = open(f'{L}/{page}', encoding='utf-8').read()
    vs = [l for l in t.split('\n') if l.startswith('const VSHARE=')]
    assert vs and all(f'"{k}":' in vs[0] for k in ks), f'{page}: VSHARE missing {ks}'
w = {f"{m['n']}": m for m in json.load(open(f'{L}/sub-water.json', encoding='utf-8'))}
assert [v['kind'] for v in w['5']['media']['videos']] == ['pre'], 'water 5: want pre'
print('213_env_water5_pre pages OK')
PY
VR=/mnt/project-files/archive/video_repos
if [ "${ENV_VIDEOS_TEST_NO_OFFLOAD:-}" = 1 ]; then echo "213_env_water5_pre: offload skipped (sandbox test only)"
else
  test -f $VR/ACTIVE || { echo "213_env_water5_pre: video repos not active; refusing to leave videos on the main site" >&2; exit 1; }
  grep -qxF '*.mp4' $HUB/.gitignore 2>/dev/null || { echo "213_env_water5_pre: $HUB/.gitignore has no *.mp4 line" >&2; exit 1; }
  python3 "$BUILD/video_offload.py" "$HUB" --report $VR/OFFLOAD_213_env_water5_pre.md || python3 "$BUILD/video_offload.py" "$HUB"
  python3 /mnt/project-files/archive/check/video_host_check.py "$HUB"
  if find "$L" -name '*.mp4' | grep -q .; then echo "213_env_water5_pre: mp4 still on the main site after offload" >&2; exit 1; fi
fi
echo "213_env_water5_pre OK"
exit 0
